def norm_sample_id(v):
    if v is None:
        return None
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    if isinstance(v, int):
        return str(v)
    s = str(v).strip()
    if re.match(r'"'^'"\\d+\\.0"'$'"', s):
        return s.split('.')[0]
    return s

def rows_from(path):
    wb = load_workbook(path, read_only=False, data_only=True)
    ws = wb.worksheets[0]
    for row in ws.iter_rows(values_only=True):
        yield list(row)

