coding_plus_splice = set(coding_terms)
coding_plus_splice.add('splice_region_variant')

splitter = re.compile(r'["'^A-Za-z0-9_]+'"')
def so_terms(value):
    if value is None:
        return set()
    terms = set([t for t in splitter.split(str(value).strip()) if t])
    return terms

def to_decimal(v):
    if v is None:
        return None
    s = str(v).strip()
    if not s:
        return None
    try:
        return Decimal(s)
    except InvalidOperation:
        return None

def boolish(v):
    if v is None:
        return None
    s = str(v).strip().lower()
    if s in ('true','yes','1'):
        return True
    if s in ('false','no','0'):
        return False
    return None

